        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control" value="@Personal.FullName"
               @onchange="e => UpdatePersonal(Personal with { FullName = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control" value="@Personal.Email"
               @onchange="e => UpdatePersonal(Personal with { Email = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control" value="@Personal.Phone"
               @onchange="e => UpdatePersonal(Personal with { Phone = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control" value="@Personal.Address"
               @onchange="e => UpdatePersonal(Personal with { Address = (string?)e.Value ?? string.Empty })" />
    </div>
</div>

<div class="mt-4 d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="Next" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public EventCallback<PersonalInfo> OnPersonalChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    private void UpdatePersonal(PersonalInfo updated)
    {
        OnPersonalChanged.InvokeAsync(updated);
    }

    private async Task Next()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Personal.FullName) ||
            string.IsNullOrWhiteSpace(Personal.Email) ||
            string.IsNullOrWhiteSpace(Personal.Phone) ||
            string.IsNullOrWhiteSpace(Personal.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail != null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Personal.Email);
            IsValidating = false;

            if (!isValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

