@page "/apply"
@using sv_a6cd55e61b464dfd88b83483ea4ea408.Models
@using sv_a6cd55e61b464dfd88b83483ea4ea408.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnNavigateToStep="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Personal="@personalInfo"
                                  OnPersonalChanged="p => personalInfo = p"
                                  OnNext="NextStep"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync" />
                break;
            case 1:
                <WorkHistoryStep Entries="@workEntries"
                                 OnEntriesChanged="e => workEntries = e"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="@references"
                                OnReferencesChanged="r => references = r"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 OnCoverLetterChanged="c => coverLetter = c"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep Personal="@personalInfo"
                            WorkEntries="@workEntries"
                            References="@references"
                            CoverLetter="@coverLetter"
                            OnEditStep="GoToStep"
                            OnBack="PreviousStep"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep = 0;

    private PersonalInfo personalInfo = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> workEntries = new() { new(string.Empty, string.Empty, DateTime.Today, null, string.Empty) };
    private List<Reference> references = new() { new(string.Empty, string.Empty, string.Empty, string.Empty), new(string.Empty, string.Empty, string.Empty, string.Empty) };
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step >= 0 && step <= 4)
            currentStep = step;
    }

    private void NextStep()
    {
        if (currentStep < 4)
            currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo,
            new WorkHistory(workEntries),
            references,
            coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
}

.step-connector.completed {
    background: #198754;
}

@page "/apply"
@using sv_a6cd55e61b464dfd88b83483ea4ea408.Models
